    nanoocp_conversion<BRepBuilderAPI_MakePolygon, TopoDS_Edge>(nb::module_::import_("nanoocp._TKBRep.TopoDS").attr("TopoDS_Edge"), true);
    nanoocp_conversion<BRepBuilderAPI_MakePolygon, TopoDS_Wire>(nb::module_::import_("nanoocp._TKBRep.TopoDS").attr("TopoDS_Wire"), true);
    nanoocp_conversion<BRepBuilderAPI_MakeShell, TopoDS_Shell>(nb::module_::import_("nanoocp._TKBRep.TopoDS").attr("TopoDS_Shell"), true);
    nanoocp_conversion<BRepBuilderAPI_MakeSolid, TopoDS_Solid>(nb::module_::import_("nanoocp._TKBRep.TopoDS").attr("TopoDS_Solid"), true);
